    _L = l
    _R = r


_COLS = [('black', Color.BLACK), ('violet', Color.VIOLET), ('blue', Color.BLUE), ('azure', Color.CYAN), ('green', Color.GREEN), ('yellow', Color.YELLOW), ('red', Color.RED), ('white', Color.WHITE), ('none', Color.NONE)]


